```react
function Score({ name }) {
  const [points, setPoints] = React.useState(0);
  return <button onClick={() => setPoints(p => p + 1)}>{name}: {points}</button>;
}
function App() {
  const [players, setPlayers] = React.useState([
    { id: "sun", name: "Sol" },
    { id: "moon", name: "Luna" }
  ]);
  return (
    <main>
      <button onClick={() => setPlayers(current => [...current].reverse())}>Reverse</button>
      <div>{players.map(player => (
        <Score key={player.id} name={player.name} />
      ))}</div>
    </main>
  );
}
```
Click Sol twice, then Reverse. Sol keeps 2 points and Luna keeps 0. The stable keys travel with their players.
